/**
 * Canonical 16-Color Indexed Artwork Assets for Bramble & Pip.
 * Extracted and quantized strictly to the Whispering Woods palette.
 * Pre-encoded as base64 data URIs for zero network egress.
 */

import type Phaser from 'phaser';

export const CANONICAL_ASSETS: Record<string, string> = {
  satchel_bg: 'data:image/png;base64,',
  pip_cameo_happy: 'data:image/png;base64,',
  pip_cameo_thinking: 'data:image/png;base64,',
  pip_cameo_winter: 'data:image/png;base64,',
  pip_cameo: 'data:image/png;base64,',
  whispering_woods_bg: 'data:image/png;base64,',
  mossy_gearbox_bg: 'data:image/png;base64,',
  mossy_hollow_bg: 'data:image/png;base64,',
  pine_ridge_bg: 'data:image/png;base64,',
  ranger_lodge_bg: 'data:image/png;base64,',
  sketchbook_bg: 'data:image/png;base64,',
  world_full_map_bg: 'data:image/png;base64,',
  beaver_sprite: 'data:image/png;base64,',
};

/**
 * Registers all canonical textures synchronously or asynchronously into the Phaser TextureManager
 * using in-memory HTMLImageElement data decoding (zero network egress).
 */
export function registerCanonicalTextures(scene: Phaser.Scene): Promise<void> {
  const entries = Object.entries(CANONICAL_ASSETS);
  return Promise.all(
    entries.map(([key, dataUri]) => {
      return new Promise<void>((resolve) => {
        if (scene.textures.exists(key)) {
          resolve();
          return;
        }
        if (typeof Image === 'undefined') {
          resolve();
          return;
        }
        const img = new Image();
        img.onload = () => {
          scene.textures.addImage(key, img);
          resolve();
        };
        img.onerror = () => {
          resolve();
        };
        img.src = dataUri;
      });
    })
  ).then(() => {});
}
